test("person terms dated scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-A", "20");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "perm-void", "clerk");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.setSetting(pg_uma, "grace-A", "5");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "25.00"}));
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33", "from": "2026-03-16", "to": "2026-03-25"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "3"})).toBeNull();
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "contact": " Ada@x "}));
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "0.04", "start": "2026-03-09", "end": "2026-04-30", "day": "15"}));
  await ui.setToday(pg_uma, "2026-04-29");
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-02-10", "to": "2026-02-25"})).toBe(true);
  await ui.setToday(pg_uma, "2026-05-05");
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "3.33", "date": "2026-03-28", "note": "n", "ref": " r-1 "}));
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-16"})).toBe(true);
  expect(await ui.importPeople(pg_uma, "Dot,B\nFay,B,3,fay@x")).toMatchObject({"added": 2, "updated": 0});
  const p_dot = await ui.personId(pg_uma, "Dot");
  const p_fay = await ui.personId(pg_uma, "Fay");
  expect(await ui.statement(pg_uma, p_dot)).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
